// MLS tools (11.16): seven member tools on CRMLS aggregates by ZIP code (mlsAreaStats.js, generated by the portfolio
// exporter sites/_tools/mls-amico-export.js; counts, medians, middle ranges and shares only, never a single sale, an
// address or an MLS number). Area Pulse, Price Path Lens, Market Pace Gauge, Where My Home Fits, Feature Lens,
// Days-to-Sold Curve, Watchers and Listings Pulse, plus the Five Years card (shown with Market Pace, same gate key).
// Rudy's broker approved them (11.16): the gate in nuancedGate.js is on for everyone. Every endpoint needs a sign-in
// (members, agents and admins; Rudy 11.17: no public page): lens.js, area-pulse.js and home-fits.js, all private, no-store.
// Phase 2 (11.16 late): 9 areas and 28 ZIP codes; days from listing to accepted offer (Days to Sold), the new
// construction and accessibility-features shares (Feature Lens), the 5-year monthly trend. Never the financing mix,
// concessions, compensation, HOA dues or Mello-Roos. Every share is null-safe: under the strict share rule the data
// module leaves a share out (null) when its base is under 20 or it would point to 1 to 4 sales, and the views then say
// so or skip it, never "null%".
// Jury test: no value estimate, no "what a feature adds", no buyer's / seller's market verdict, no ranking except the
// approved Trending activity sort, nothing called best or hot, watchers are never called buyers or demand, any price
// range is "recent sold range, not an appraisal", every card carries the CRMLS source line. Pure except watcherCounts.
// The views carry finished plain-text lines; mls-tools.js (the app) only escapes and draws them.
import { MLS_AREA_STATS } from './mlsAreaStats.js';
import { DEMO_EMAIL_PATTERN, escapeHtml } from './util.js';
import { EMAIL_POSTAL_LINE } from './email.js';
import { WISHLIST_ITEMS } from './listingTerms.js';

export const MLS_TOOLS = ['areaPulse', 'pricePath', 'marketPace', 'homeFits', 'featureLens', 'daysCurve', 'watchersPulse'];
export const LENS_TOOLS = ['pricePath', 'marketPace', 'featureLens', 'daysCurve', 'watchersPulse'];
// The Area Pulse monthly email: built (areaPulseEmail) and switched OFF. Nothing sends it, and no job runs it. Turning
// it on needs Rudy's OK on the wording, an opt-in column and a one-click stop route (MLS-TOOLS-NOTES.md).
export const AREA_PULSE_EMAIL_LIVE = false;

export const STATS = MLS_AREA_STATS;
const RULES = (STATS && STATS.rules) || {};
const LENS_MIN = RULES.lensMin || { path: 10, within: 20, curve: 30, pace: 10, fit: 20 };
export const RANGE_LABEL = RULES.rangeLabel || 'recent sold range, not an appraisal';
export const FEATURE_LINE = RULES.featureLine || 'This is what sold, not what a feature adds.';
export const TRENDING_LABEL = RULES.trendingLabel || 'Trending: most homes sold in the last 90 days';
export const WATCHERS_MIN = 5, WISHERS_MIN = 10;

// ---- Words (exact; mls-tools.js prints what the views carry, and tools/mls-tools-test.mjs checks them) ----
export const TYPES = { all: 'All home types', sfr: 'Single-family homes', attached: 'Condos and townhomes' };
export const HEADINGS = {
  areaPulse: 'Area Pulse', pricePath: 'Price Path', marketPace: 'Market Pace', homeFits: 'Where My Home Fits',
  featureLens: 'Feature Lens', daysCurve: 'Days to Sold', watchersPulse: 'Watchers and Listings', fiveYear: 'Five Years, Month by Month',
};
// The Five Years card rides on the marketPace gate key (no gate key of its own).
export const FIVE_YEAR_GATE = 'marketPace';
// Rudy 11.17: the Five Years months of supply keeps its figure, with an asterisk and this footnote under the chart.
export const TREND_MOS_MARK = 'Months of supply*';
export const TREND_LINE = '*Months of supply here = homes for sale that month divided by homes sold that month, so it can differ from the 12-month figure on the Market Pace gauge.';
export const TREND_TYPE_LINE = 'The monthly CRMLS stats cover all home types together.';
export const OFFER_LINE = 'Days from listing to accepted offer: the purchase contract date minus the listing date, as entered in the MLS.';
export const NOT_SPLIT_LINE = 'not split out (small counts)';
export const CTA = { text: 'Thinking about selling? Post a pre-listing showcase and local agents weigh in on your price.', button: 'Post a pre-listing' };
export const FITS_DRAFT_BUTTON = 'Start my showcase with these details';
export const FITS_LINE = 'Sizes, years and counts only: no price and no appraisal.';
export const FITS_CARRY_LINE = 'ZIP, home type, beds, baths, size and garage spaces carry over to your showcase. Lot, year built and stories stay here.';
export const PACE_LINE = 'Months of supply: active listings on the MLS divided by the homes sold per month over the last 12 months.';
export const DAYS_LINE = 'Days on market as the MLS counts them.';
export const NOT_COVERED_LINE = (zips) => `No MLS numbers for this ZIP code yet. So far they cover ${listWords(zips)}.`;
export const NO_WATCH_AREAS_LINE = 'Watch a ZIP code in your watch areas and its numbers show up here.';
export const FITS_ZIP_ERROR = 'Pick one of the ZIP codes listed.';
export const FITS_NUMBER_ERROR = 'Use whole numbers in a normal range for your home (baths can end in .5).';

const isObj = v => !!v && typeof v === 'object' && !Array.isArray(v);
const num = n => Number(n).toLocaleString('en-US');
const money = n => `$${num(n)}`;
const has = c => isObj(c) && c.n != null;
function listWords(xs) { const a = xs.slice(); return a.length <= 1 ? a.join('') : `${a.slice(0, -1).join(', ')} and ${a[a.length - 1]}`; }
const fewer3 = v => (v == null ? 'fewer than 3' : num(v));
const pct = v => (v == null ? null : `${v}%`);
// "29% sold above list, 23% at list, 48% below", naming the parts the data module withheld instead of a number:
// parts = [[words(v), v, name]]. "43% below; above list and at list: not split out (small counts)".
function partsText(parts, sep = ', ') {
  const shown = parts.filter(([, v]) => v != null).map(([words, v]) => words(v));
  const hidden = parts.filter(([, v]) => v == null).map(([, , name]) => name);
  if (!hidden.length) return shown.join(sep);
  return `${shown.length ? `${shown.join(sep)}; ` : ''}${listWords(hidden)}: ${NOT_SPLIT_LINE}`;
}
// Cumulative "within N days" shares: the ones shown, in order ("7 days: 20% · 14 days: 39%"). A withheld one (null: the data module's
// cumulative guard holds a figure 1 to 4 sales from the one before it, or one that stands for 1 to 4) is named after the shown ones,
// the Price Path way: "7 days: 20% · 30 days: 45%; 14 days: not split out (small counts)". Nothing shown = "".
function withinText(w, days) {
  const shown = days.filter(d => w && w[`d${d}`] != null).map(d => `${d} days: ${w[`d${d}`]}%`).join(' · ');
  const held = days.filter(d => w && w[`d${d}`] === null);
  return shown && held.length ? `${shown}; ${listWords(held.map(d => `${d} days`))}: ${NOT_SPLIT_LINE}` : shown;
}
const MONTHS3 = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const ymShort = ym => `${MONTHS3[Number(ym.slice(5, 7)) - 1]} ${ym.slice(0, 4)}`;
const ymLong = ym => `${MONTHS_LONG[Number(ym.slice(5, 7)) - 1]} ${ym.slice(0, 4)}`;
function activeLine(a, lead = 'On the MLS now') {
  if (has(a) && a.status) return null;
  return `${lead}: ${a && a.nLabel && a.nLabel !== 'fewer than 3' ? a.nLabel : 'fewer than 3 listings'}`;
}

// ---- Scopes: a covered ZIP or a whole area ----
export function coveredZips() { return Object.keys((STATS && STATS.zips) || {}).sort(); }
export function scopeList() {
  const areas = Object.entries((STATS && STATS.areas) || {}).sort((a, b) => a[1].name.localeCompare(b[1].name))
    .map(([key, A]) => ({ key, label: A.label || `${A.name} (${A.place})` }));
  const zips = coveredZips().map(z => ({ key: z, label: `ZIP ${z} (${STATS.zips[z].place})` }));
  return [...areas, ...zips];
}
// { kind: 'zip'|'area', key, Z, A } or null for anything not covered.
export function resolveScope(key) {
  const k = String(key || '').trim().toLowerCase();
  if (!STATS) return null;
  if (/^\d{5}$/.test(k) && Object.hasOwn(STATS.zips, k)) { const Z = STATS.zips[k]; return { kind: 'zip', key: k, Z, A: STATS.areas[Z.area], name: Z.name }; }
  if (Object.hasOwn(STATS.areas, k)) { const A = STATS.areas[k]; return { kind: 'area', key: k, Z: null, A, name: A.name }; }
  return null;
}
export const typeKey = t => (Object.hasOwn(TYPES, t) ? t : 'all');
export function credit(scope) { return scope && scope.A && scope.A.source ? scope.A.source.full : ''; }

// The cell for a scope, widened from the ZIP to its whole area when the ZIP's cell is under its floor.
// get(lens) -> cell. Returns { cell, where, widened, fewer } (cell null when even the area is under its floor).
function widen(scope, get, ok = has) {
  const tries = scope.kind === 'zip' ? [[scope.Z.lens, scope.Z.name], [scope.A.lens, scope.A.name]] : [[scope.A.lens, scope.A.name]];
  let fewer = '';
  for (const [lens, where] of tries) {
    const c = lens ? get(lens) : null;
    if (ok(c)) return { cell: c, where, widened: where !== scope.name, fewer };
    if (!fewer && c && c.nLabel) fewer = c.nLabel;
  }
  return { cell: null, where: scope.name, widened: false, fewer: fewer || 'fewer than 5 sales' };
}
function scopeLine(scope, type, got) {
  const base = `${got.where} · ${TYPES[type]}`;
  if (!got.widened) return base;
  const why = /^fewer /.test(got.fewer) ? `${scope.name} has ${got.fewer} for this` : `${scope.name}: ${got.fewer}`;
  return `${base} (${why}, so this is the whole area)`;
}
function view(tool, scope, lines, extra = {}) {
  return { tool, heading: HEADINGS[tool], lines: lines.filter(Boolean), credit: credit(scope), ...extra };
}

// ---- 1. Area Pulse: one card per watch area ----
export function areaPulseCard(zip, label = '') {
  const heading = `ZIP ${zip}${label ? ` · ${label}` : ''}`;
  const scope = resolveScope(zip);
  if (!scope || scope.kind !== 'zip') return { tool: 'areaPulse', zip: String(zip), heading, covered: false, lines: [NOT_COVERED_LINE(coveredZips())], credit: '' };
  const { Z } = scope;
  const lines = [];
  if (has(Z.closed)) {
    lines.push(`${num(Z.closed.n)} homes sold in the last 12 months${Z.sold90 != null ? `, ${num(Z.sold90)} of them in the last 90 days` : ''}`);
    if (Z.closed.price) lines.push(`Middle price range ${money(Z.closed.price.lo)} to ${money(Z.closed.price.hi)}, median ${money(Z.closed.price.med)} (${RANGE_LABEL})`);
    if (Z.closed.days) lines.push(`Median days on market: ${num(Z.closed.days.med)}`);
  } else lines.push(`Homes sold in the last 12 months: ${Z.closed.nLabel}`);
  const od = Z.cols && Z.cols.offerDays;
  if (has(od) && od.days) lines.push(`Median days from listing to accepted offer: ${num(od.days.med)}`);
  if (has(Z.active) && Z.active.status) {
    const s = Z.active.status;
    lines.push(`On the MLS now: ${fewer3(s.active)} active · ${fewer3(s.pending)} pending · ${fewer3(s.underContract)} active under contract`);
  } else lines.push(activeLine(Z.active));
  return { tool: 'areaPulse', zip: scope.key, heading, covered: true, lines, credit: credit(scope) };
}

// ---- 2. Price Path Lens ----
export function pricePathView(scope, type) {
  const t = typeKey(type);
  const got = widen(scope, L => L.byType[t] && L.byType[t].path);
  if (!got.cell) return view('pricePath', scope, [`${scope.name} · ${TYPES[t]}: ${got.fewer}`], { scope: scopeLine(scope, t, got) });
  const p = got.cell;
  const lines = [];
  if (p.stl) {
    const split = partsText([[v => `${v}% sold above list`, p.stl.over, 'above list'], [v => `${v}% at list`, p.stl.at, 'at list'], [v => `${v}% below`, p.stl.under, 'below list']]);
    lines.push(`Sale price vs. final list price: median ${p.stl.med}%${split ? `. ${split}` : ''} (${num(p.stl.n)} sales)`);
  }
  if (p.cut && p.cut.share != null) lines.push(`${p.cut.share}% of sales had a price cut (final list price below the original), out of ${num(p.cut.n)}`);
  else if (p.cut) lines.push(`Sales with a price cut (final list price below the original): ${p.cut.shareLabel || `share ${NOT_SPLIT_LINE}`}`);
  if (p.cutSize) lines.push(`Typical cut: ${p.cutSize.med}% of the original list price (middle range ${p.cutSize.lo}% to ${p.cutSize.hi}%, ${num(p.cutSize.n)} sales with a cut)`);
  const side = (label, c) => (has(c) && c.days ? `${label}: median ${num(c.days.med)} days on market (middle range ${num(c.days.lo)} to ${num(c.days.hi)}, ${num(c.n)} sales)` : `${label}: ${(c && c.nLabel) || 'fewer than 10 sales'}`);
  lines.push(side('Sold without a price cut', p.noCut), side('Sold after a price cut', p.afterCut));
  // By sold price band at the same level (all home types).
  const lens = got.where === scope.A.name ? scope.A.lens : scope.Z.lens;
  const rows = (lens.bands || []).map(b => (has(b.path) && b.path.stl
    ? [b.label, num(b.path.n), `${b.path.stl.med}%`, b.path.cut ? (pct(b.path.cut.share) || b.path.cut.shareLabel || NOT_SPLIT_LINE) : '']
    : [b.label, (b.path && b.path.nLabel) || 'fewer than 10 sales', '', '']));
  return view('pricePath', scope, lines, {
    scope: scopeLine(scope, t, got),
    table: { caption: `${got.where} by sold price band, all home types`, head: ['Price band', 'Sales', 'Median sale-to-list', 'Had a price cut'], rows },
  });
}

// ---- 3. Market Pace Gauge (neutral: a number on a scale, no verdict) ----
export const PACE_SCALE_MAX = 8;
export function marketPaceView(scope, type) {
  const t = typeKey(type);
  const got = widen(scope, L => L.byType[t] && L.byType[t].pace);
  const lines = [];
  let gauge = null;
  if (got.cell) {
    const c = got.cell;
    if (c.mos != null) { lines.push(`Months of supply: ${c.mos.toFixed(1)}`); gauge = { value: c.mos, max: PACE_SCALE_MAX, label: `${c.mos.toFixed(1)} months of supply on a scale of 0 to ${PACE_SCALE_MAX} or more` }; }
    lines.push(`${num(c.n)} listings on the MLS now${c.pendingShare != null ? `, ${c.pendingShare}% of them pending or under contract` : ` (pending share: ${c.pendingLabel || 'fewer than 10 listings'})`}`);
  } else lines.push(`${scope.name} · ${TYPES[t]}: ${got.fewer}`);
  const lens = got.where === scope.A.name || !scope.Z ? scope.A.lens : scope.Z.lens;
  const rows = (lens.bands || []).map(b => {
    const c = b.pace;
    if (!has(c)) return [b.label, (c && c.nLabel) || 'fewer than 3', '', ''];
    return [b.label, num(c.n), c.mos != null ? c.mos.toFixed(1) : '', c.pendingShare != null ? `${c.pendingShare}%` : (c.pendingLabel || '')];
  });
  const tr = scope.A.trendingZips;
  const trending = tr && tr.ranked && tr.ranked.length
    ? `${tr.label}: ${tr.ranked.map(r => `${r.name} (${num(r.sold90)})`).join(', ')}` : '';
  return view('marketPace', scope, lines, {
    scope: scopeLine(scope, t, got), gauge, note: PACE_LINE, trending,
    table: { caption: `${got.where} by price band (listings by list price, sales by sold price)`, head: ['Price band', 'Listings now', 'Months of supply', 'Pending or under contract'], rows },
  });
}

// ---- The new-column cells (phase 2): which set a scope and home type read ----
// An area has them by home type; a ZIP has them for all home types together (then the line says so). Coronado's export
// has none of these columns, so its cards simply leave the lines out.
function colsFor(scope, type) {
  const t = typeKey(type);
  if (scope.kind === 'area') {
    const C = t === 'all' ? scope.A.cols : scope.A.colsByType && scope.A.colsByType[t];
    return C ? { C, tail: '' } : null;
  }
  const C = scope.Z && scope.Z.cols;
  return C ? { C, tail: t === 'all' ? '' : ` (all home types in ${scope.name})` } : null;
}
function shareLine(lead, c, tail, ofWhat = 'sales') {
  if (!c) return '';
  if (c.n == null) return `${lead}: ${c.nLabel || 'fewer than 20 sales'}${tail}`;
  if (c.share == null) return `${lead}: ${c.shareLabel || NOT_SPLIT_LINE}${/ of [\d,]+$/.test(c.shareLabel || '') ? ` ${ofWhat}` : ''}${tail}`;
  return `${lead}: ${c.share}% of ${num(c.n)} ${ofWhat}${tail}`;
}
export function colsLines(scope, type) {
  const got = colsFor(scope, type);
  if (!got) return { offer: [], features: [] };
  const { C, tail } = got;
  const offer = [];
  const od = C.offerDays;
  if (has(od) && od.days) {
    offer.push(`Days from listing to accepted offer: median ${num(od.days.med)} (middle range ${num(od.days.lo)} to ${num(od.days.hi)}, ${num(od.n)} sales)${tail}`);
    if (od.within) {
      const w = withinText(od.within, [7, 14, 30]);
      offer.push(w ? `Accepted offer within ${w}` : `Accepted offer within 7, 14 or 30 days: ${NOT_SPLIT_LINE}`);
    } else offer.push(`Accepted offer within 7, 14 or 30 days: ${od.withinLabel || 'fewer than 20 sales'}`);
  } else if (od) offer.push(`Days from listing to accepted offer: ${od.nLabel || 'fewer than 5 sales'}${tail}`);
  const features = [
    shareLine('Marked new construction in the MLS', C.newConstruction, tail, 'sales where the field is filled in'),
    shareLine('Homes with accessibility features', C.accessibility, tail),
  ].filter(Boolean);
  return { offer, features };
}

// ---- 5. Feature Lens: with and without, side by side, never a difference ----
const FEATURE_ORDER = ['privatePool', 'communityPool', 'singleStory', 'garage3', 'solar', 'view', 'viewMountain', 'viewCityLights', 'viewHillsValley', 'viewParkGreenbelt', 'viewWater', 'viewOcean', 'viewBay', 'viewGolf', 'viewPanoramic'];
export function featureLensView(scope, type) {
  const t = typeKey(type);
  // Feature sides exist for single-family homes and for all home types; condos and townhomes read the all-types set.
  const set = t === 'sfr' ? 'sfr' : 'all';
  const tries = scope.kind === 'zip' ? [[scope.Z.features, scope.Z.name], [scope.A.features, scope.A.name]] : [[scope.A.features, scope.A.name]];
  let feats = null, where = scope.name;
  for (const [f, w] of tries) { if (f && f[set] && Object.keys(f[set]).length) { feats = f[set]; where = w; break; } }
  const shownType = set === 'sfr' ? TYPES.sfr : TYPES.all;
  const scopeText = `${where} · ${shownType}${where !== scope.name ? ` (${scope.name} has fewer than 5 sales on a side, so this is the whole area)` : ''}`;
  const extra = colsLines(scope, t).features;
  if (!feats) return view('featureLens', scope, ['Fewer than 5 sales on a side for every feature here.', ...extra], { scope: scopeText, note: FEATURE_LINE });
  const cellText = c => (has(c)
    ? [num(c.n), c.ppsf ? money(c.ppsf.med) : '', c.days ? num(c.days.med) : '', c.stl ? `${c.stl.med}%` : '']
    : [c && c.nLabel ? c.nLabel : 'fewer than 5 sales', '', '', '']);
  const rows = [];
  for (const k of FEATURE_ORDER) {
    const f = feats[k];
    if (!f) continue;
    rows.push([f.label, 'With', ...cellText(f.with)], ['', 'Without', ...cellText(f.without)]);
  }
  return view('featureLens', scope, extra, {
    scope: scopeText, note: FEATURE_LINE,
    table: { caption: `What sold with and without each feature, ${where}`, head: ['Feature', '', 'Sales', 'Median $ per sq ft', 'Median days on market', 'Median sale-to-list'], rows },
  });
}

// ---- 6. Days-to-Sold Curve ----
export function daysCurveView(scope, type) {
  const t = typeKey(type);
  const got = widen(scope, L => L.byType[t] && L.byType[t].curve);
  const offer = colsLines(scope, t).offer;
  const note = offer.length ? `${DAYS_LINE} ${OFFER_LINE}` : DAYS_LINE;
  if (!got.cell) return view('daysCurve', scope, [`${scope.name} · ${TYPES[t]}: ${got.fewer}`, ...offer], { scope: scopeLine(scope, t, got), note });
  const c = got.cell;
  const lines = [];
  if (c.days) lines.push(`Median ${num(c.days.med)} days on market (middle range ${num(c.days.lo)} to ${num(c.days.hi)}, ${num(c.n)} sales)`);
  const w = c.within ? withinText(c.within, [7, 14, 30, 60, 90]) : '';
  if (w) lines.push(`Sold within ${w}`);
  else if (c.within) lines.push(`Sold within 7, 14, 30, 60 or 90 days: ${NOT_SPLIT_LINE}`);
  else lines.push(`Shares by week: ${c.withinLabel || 'fewer than 20 sales'}`);
  lines.push(...offer);
  // Points the data module withheld (null) are left off the curve, never drawn as 0.
  const pts = Array.isArray(c.curve) && c.n >= LENS_MIN.curve ? c.curve.filter(p => p && p.share != null).map(p => ({ d: p.d, share: p.share })) : [];
  const curve = pts.length >= 2 ? pts : null;
  return view('daysCurve', scope, lines, {
    scope: scopeLine(scope, t, got), note, curve,
    curveLabel: curve ? `Share of ${num(c.n)} sales sold by each day on market, from day ${curve[0].d} to day ${curve[curve.length - 1].d}`
      : c.n >= LENS_MIN.curve && Array.isArray(c.curve) ? `Too few separate points to draw the curve (${NOT_SPLIT_LINE}).` : (c.curveLabel || 'The curve needs 30 or more sales.'),
  });
}

// ---- Five Years, Month by Month (phase 2; gate key marketPace) ----
// CRMLS monthly stats by ZIP, January 2021 on (the partial current month left out): homes sold each month and months of
// supply each month, plus homes sold per year. No prices, no expired-listing counts. A ZIP that isn't in the monthly
// stats widens to its area, which says which ZIP it leaves out. The series are numbers for the app's two SVG charts.
export function fiveYearView(scope, type) {
  const t = typeKey(type);
  const T = scope.kind === 'zip' && scope.Z.trend && !scope.Z.trend.missing ? scope.Z.trend : null;
  const useArea = !T;
  const tr = T || (scope.A.trend && !scope.A.trend.missing ? scope.A.trend : null);
  const where = useArea ? scope.A.name : scope.name;
  const typeNote = t === 'all' ? '' : ` (${TREND_TYPE_LINE.replace(/\.$/, '').replace(/^The/, 'the')})`;
  if (!tr || !Array.isArray(tr.months) || !tr.months.length) {
    return view('fiveYear', scope, [`No monthly CRMLS stats for ${scope.name} yet.`], { scope: `${scope.name} · ${TYPES.all}`, credit: '' });
  }
  const missing = useArea && Array.isArray(tr.missingZips) ? tr.missingZips : [];
  const widenedWhy = useArea && scope.kind === 'zip' ? ` (${scope.name} is ${scope.Z.trend && scope.Z.trend.missingLabel ? scope.Z.trend.missingLabel : 'not in the monthly CRMLS stats export'}, so this is the whole area)` : '';
  const lines = [];
  const years = (tr.years || []).map(y => `${y.label}: ${y.sold == null ? 'fewer than 5' : num(y.sold)}`);
  if (years.length) lines.push(`Homes sold by year: ${years.join(' · ')}`);
  const last = [...tr.months].reverse().find(m => m.mos != null);
  if (last) lines.push(`${TREND_MOS_MARK}, ${ymLong(last.ym)}: ${last.mos.toFixed(1)}`);
  if (missing.length && scope.kind === 'area') lines.push(`ZIP ${listWords(missing)} ${missing.length === 1 ? 'is' : 'are'} ${tr.missingLabel || 'not in the monthly CRMLS stats export'}, so ${missing.length === 1 ? 'it is' : 'they are'} left out here.`);
  const months = tr.months.map(m => ({ ym: m.ym, label: ymShort(m.ym), sold: m.sold == null ? null : m.sold, mos: m.mos == null ? null : m.mos }));
  const yearTicks = [];
  months.forEach((m, i) => { if (m.ym.endsWith('-01') || i === 0) yearTicks.push({ at: i, label: m.ym.slice(0, 4) }); });
  const soldMax = Math.max(0, ...months.map(m => m.sold || 0));
  const mosMax = Math.max(0, ...months.map(m => m.mos || 0));
  const notes = [tr.dropped && tr.dropped.label ? `${tr.dropped.label.replace(/^./, c => c.toUpperCase())}.` : ''].filter(Boolean).join(' ');
  return {
    tool: 'fiveYear', heading: HEADINGS.fiveYear, lines,
    scope: `${where} · ${TYPES.all} · ${tr.label}${widenedWhy}${typeNote}`,
    note: notes, footnote: TREND_LINE, credit: tr.source && tr.source.full ? tr.source.full : '',
    trend: {
      months, yearTicks, soldMax, mosMax: Math.ceil(mosMax),
      soldLabel: `Homes sold each month, ${tr.label} (bar height from 0 to ${num(soldMax)})`,
      mosLabel: `${TREND_MOS_MARK} each month, ${tr.label} (line height from 0 to ${Math.ceil(mosMax)})`,
    },
  };
}

// ---- 4. Where My Home Fits (no prices; nothing stored) ----
const FIT_RANGES = { beds: [0, 20], baths: [0, 20], sqft: [200, 20000], lot: [200, 2000000], year: [1850, new Date().getUTCFullYear() + 1], stories: [1, 4], garage: [0, 10] };
export function validateHomeFits(input) {
  const src = isObj(input) ? input : {};
  const zip = String(src.zip || '').trim();
  const scope = resolveScope(zip);
  if (!scope || scope.kind !== 'zip') return { error: FITS_ZIP_ERROR };
  const out = { zip, type: typeKey(src.type) };
  for (const [k, [lo, hi]] of Object.entries(FIT_RANGES)) {
    const v = src[k];
    if (v === undefined || v === null || String(v).trim() === '') continue;
    const n = Number(String(v).trim());
    const okStep = k === 'baths' ? Number.isInteger(n * 2) : Number.isInteger(n);
    if (!Number.isFinite(n) || !okStep || n < lo || n > hi) return { error: FITS_NUMBER_ERROR };
    out[k] = n;
  }
  return { data: out };
}
// "About 6 in 10 recent sales were smaller": how many of the nine decile cut points sit below the value.
export function stripPosition(strip, v) {
  if (!isObj(strip) || v == null) return null;
  const cuts = [10, 20, 30, 40, 50, 60, 70, 80, 90].map(p => strip[`p${p}`]).filter(x => x != null);
  if (cuts.length !== 9) return null;
  return cuts.filter(x => x < v).length;
}
function positionWords(k, word) {
  if (k === 0) return `Fewer than 1 in 10 recent sales ${word}.`;
  if (k === 9) return `More than 9 in 10 recent sales ${word}.`;
  return `About ${k} in 10 recent sales ${word}.`;
}
const BUCKETS = {
  beds: [['upTo2', '2 or fewer', 0, 2], ['three', '3', 3, 3], ['four', '4', 4, 4], ['fivePlus', '5 or more', 5, 99]],
  baths: [['upTo2', 'fewer than 3', 0, 2.99], ['three', '3', 3, 3.99], ['fourPlus', '4 or more', 4, 99]],
  garage: [['upTo1', '0 or 1', 0, 1], ['two', '2', 2, 2], ['threePlus', '3 or more', 3, 99]],
  stories: [['one', '1', 1, 1], ['two', '2', 2, 2], ['threePlus', '3 or more', 3, 99]],
};
function bucketLine(label, shares, key, v) {
  if (!isObj(shares) || v == null) return '';
  const defs = BUCKETS[key];
  const mine = defs.find(([, , lo, hi]) => v >= lo && v <= hi);
  if (!mine) return '';
  // A bucket the data module withheld (null) is named, never given a number: "3 and 3 or more: not split out".
  const others = defs.filter(d => d !== mine);
  const parts = [];
  if (shares[mine[0]] != null) parts.push(`${shares[mine[0]]}% of recent sales had ${mine[1]} too`);
  parts.push(...others.filter(([k]) => shares[k] != null).map(([k, words]) => `${words}: ${shares[k]}%`));
  const hidden = defs.filter(([k]) => shares[k] == null).map(([, words]) => words);
  if (hidden.length) parts.push(`${listWords(hidden)}: ${NOT_SPLIT_LINE}`);
  return `${label}: ${v}. ${parts.join(' · ')}`;
}
export function homeFitsView(data) {
  const scope = resolveScope(data.zip);
  const t = typeKey(data.type);
  const got = widen(scope, L => L.byType[t] && L.byType[t].fit);
  const draft = {
    zip: data.zip, propertyType: t === 'sfr' ? 'Single Family Home' : '',
    beds: data.beds ?? null, baths: data.baths ?? null, sqft: data.sqft ?? null, garage: data.garage ?? null,
  };
  if (!got.cell) return { ...view('homeFits', scope, [`${scope.name} · ${TYPES[t]}: ${got.fewer}`], { scope: scopeLine(scope, t, got), note: FITS_LINE }), draft };
  const c = got.cell;
  const lines = [];
  const pos = (strip, v, word, label, unit = '') => { const k = stripPosition(strip, v); return k == null ? '' : `${label}: ${num(v)}${unit}. ${positionWords(k, word)}`; };
  lines.push(pos(c.sqftStrip, data.sqft, 'were smaller', 'Size', ' sq ft'));
  if (t !== 'attached') lines.push(pos(c.lotStrip, data.lot, 'had smaller lots', 'Lot', ' sq ft'));
  const yk = stripPosition(c.builtStrip, data.year);
  lines.push(yk == null ? '' : `Year built: ${data.year}. ${positionWords(yk, 'were built earlier')}`);
  lines.push(bucketLine('Bedrooms', c.beds, 'beds', data.beds), bucketLine('Bathrooms', c.baths, 'baths', data.baths));
  lines.push(bucketLine('Garage spaces', c.garage, 'garage', data.garage), bucketLine('Stories', c.stories, 'stories', data.stories));
  const filled = lines.filter(Boolean);
  if (!filled.length) filled.push('Add a size, a year or a count above to see where your home lands.');
  return { ...view('homeFits', scope, filled, { scope: `Compared with ${num(c.n)} recent sales: ${scopeLine(scope, t, got)}`, note: FITS_LINE, carry: FITS_CARRY_LINE, button: FITS_DRAFT_BUTTON }), draft };
}

// ---- 7. Watchers and Listings Pulse ----
// The Amico Haus side in TWO statements (the second only when 10+ owners here have a wish list). Members who watch
// the ZIP (active, not demo) and owners with an open home on Amico Haus in it who listed what matters to them besides
// price. Head-start homes, buyer-only profiles and paused listings are left out. Counts only, never a name.
const OWNER_HOMES = `SELECT l.user_id AS user_id, l.terms_wishlist_json AS t FROM listings l
     WHERE l.zip = ?1 AND l.status = 'active' AND l.hidden_at IS NULL AND l.is_buyer_only = 0 AND l.head_start_until IS NULL
   UNION ALL SELECT p.user_id, p.terms_wishlist_json FROM pre_listings p
     WHERE p.zip = ?1 AND p.status = 'open' AND (p.head_start_until IS NULL OR p.head_start_until <= datetime('now'))`;
export async function watcherCounts(db, zip) {
  const row = await db.prepare(
    `SELECT (SELECT COUNT(DISTINCT w.user_id) FROM watch_areas w JOIN users u ON u.id = w.user_id
              WHERE w.zip = ?1 AND u.status = 'active' AND u.email NOT LIKE ?2) AS watchers,
            (SELECT COUNT(DISTINCT h.user_id) FROM (${OWNER_HOMES}) h JOIN users u ON u.id = h.user_id
              WHERE u.status = 'active' AND u.email NOT LIKE ?2 AND json_valid(h.t) AND json_array_length(h.t) > 0) AS wishers`
  ).bind(String(zip), DEMO_EMAIL_PATTERN).first();
  const watchers = Number(row && row.watchers) || 0, wishers = Number(row && row.wishers) || 0;
  let wishes = [];
  if (wishers >= WISHERS_MIN) {
    const rows = await db.prepare(
      `SELECT j.value AS item, COUNT(DISTINCT h.user_id) AS n FROM (${OWNER_HOMES}) h JOIN users u ON u.id = h.user_id, json_each(h.t) j
       WHERE u.status = 'active' AND u.email NOT LIKE ?2 AND json_valid(h.t)
       GROUP BY j.value ORDER BY n DESC, j.value ASC LIMIT 8`
    ).bind(String(zip), DEMO_EMAIL_PATTERN).all();
    wishes = (rows.results || []).filter(r => Object.hasOwn(WISHLIST_ITEMS, r.item)).slice(0, 3).map(r => ({ item: r.item, n: Number(r.n) }));
  }
  return { watchers, wishers, wishes };
}
export function watchersPulseView(scope, counts) {
  if (!scope || scope.kind !== 'zip') return view('watchersPulse', scope, ['Pick a ZIP code to see how many members watch it.'], { scope: scope ? scope.name : '' });
  const { watchers = 0, wishers = 0, wishes = [] } = counts || {};
  const zip = scope.key;
  const lines = [watchers >= WATCHERS_MIN ? `${num(watchers)} Amico Haus members watch ZIP ${zip}` : `Fewer than ${WATCHERS_MIN} Amico Haus members watch ZIP ${zip} so far`];
  const a = scope.Z.active;
  lines.push(has(a) && a.status
    ? `On the MLS now: ${num(a.n)} listings (${fewer3(a.status.active)} active, ${fewer3(a.status.pending)} pending, ${fewer3(a.status.underContract)} active under contract)`
    : activeLine(a));
  if (wishers >= WISHERS_MIN && wishes.length) {
    lines.push(`What owners here wish for besides price (${num(wishers)} owners with homes on Amico Haus): ${wishes.map(w => `${WISHLIST_ITEMS[w.item]} (${w.n} of ${wishers})`).join(' · ')}`);
  } else lines.push(`What owners here wish for besides price: fewer than ${WISHERS_MIN} owners with homes on Amico Haus have a wish list so far`);
  return view('watchersPulse', scope, lines, { scope: scope.name, note: 'Member and wish-list counts are from Amico Haus; listing counts are from the MLS.' });
}

// ---- The Area Pulse monthly email (built, OFF: AREA_PULSE_EMAIL_LIVE) ----
export function areaPulseEmail(cards, { stopUrl = '' } = {}) {
  const covered = (cards || []).filter(c => c && c.covered);
  const subject = 'Your watch areas this month';
  const credits = [...new Set(covered.map(c => c.credit).filter(Boolean))];
  const text = [
    ...covered.flatMap(c => [c.heading, ...c.lines.map(l => `- ${l}`), '']),
    ...credits, '',
    'You get this because you watch these ZIP codes on Amico Haus and turned on the monthly Area Pulse.',
    stopUrl ? `Stop these emails: ${stopUrl}` : '',
    EMAIL_POSTAL_LINE,
  ].filter((l, i, all) => l !== '' || (i > 0 && all[i - 1] !== '')).join('\n');
  const html = [
    ...covered.map(c => `<h3>${escapeHtml(c.heading)}</h3><ul>${c.lines.map(l => `<li>${escapeHtml(l)}</li>`).join('')}</ul>`),
    ...credits.map(x => `<p>${escapeHtml(x)}</p>`),
    '<p>You get this because you watch these ZIP codes on Amico Haus and turned on the monthly Area Pulse.</p>',
    stopUrl ? `<p><a href="${escapeHtml(stopUrl)}">Stop these emails</a></p>` : '',
    `<p>${escapeHtml(EMAIL_POSTAL_LINE)}</p>`,
  ].join('');
  return { subject, text, html, live: AREA_PULSE_EMAIL_LIVE };
}
